package com.pawsshop.model; import javax.persistence.*;
@Entity public class Appointment { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private String petName; private String customerName; private String service; private String date; private String time; private String status; private Long ownerId; private Long petId; private Long serviceId; private Long doctorId; @Column(length=2000) private String consultationNotes;
 public Long getOwnerId(){return ownerId;} public void setOwnerId(Long v){ownerId=v;} public Long getPetId(){return petId;} public void setPetId(Long v){petId=v;} public Long getServiceId(){return serviceId;} public void setServiceId(Long v){serviceId=v;} public Long getDoctorId(){return doctorId;} public void setDoctorId(Long v){doctorId=v;} public String getConsultationNotes(){return consultationNotes;} public void setConsultationNotes(String v){consultationNotes=v;}
 public Long getId(){return id;} public void setId(Long v){id=v;} public String getPetName(){return petName;} public void setPetName(String v){petName=v;} public String getCustomerName(){return customerName;} public void setCustomerName(String v){customerName=v;} public String getService(){return service;} public void setService(String v){service=v;} public String getDate(){return date;} public void setDate(String v){date=v;} public String getTime(){return time;} public void setTime(String v){time=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} }
